database_schema:
CREATE TABLE equipment_assets (
    asset_id BIGINT PRIMARY KEY,
    asset_code VARCHAR(40) NOT NULL UNIQUE,
    equipment_name VARCHAR(120) NOT NULL
);

CREATE TABLE downtime_records (
    downtime_id BIGINT PRIMARY KEY,
    asset_id BIGINT NOT NULL REFERENCES equipment_assets(asset_id),
    started_at TIMESTAMP NOT NULL,
    ended_at TIMESTAMP,
    CHECK (ended_at IS NULL OR ended_at >= started_at)
);

CREATE TABLE maintenance_work_orders (
    work_order_id BIGINT PRIMARY KEY,
    status VARCHAR(20) NOT NULL CHECK (status IN ('open', 'in_progress', 'completed', 'cancelled')),
    completed_at TIMESTAMP
);

CREATE TABLE spare_parts (
    part_id BIGINT PRIMARY KEY,
    part_number VARCHAR(50) NOT NULL UNIQUE,
    description VARCHAR(200) NOT NULL
);

CREATE TABLE spare_part_usage (
    usage_id BIGINT PRIMARY KEY,
    work_order_id BIGINT NOT NULL REFERENCES maintenance_work_orders(work_order_id),
    part_id BIGINT NOT NULL REFERENCES spare_parts(part_id),
    quantity_issued NUMERIC(12, 2) NOT NULL CHECK (quantity_issued >= 0),
    unit_cost_at_issue NUMERIC(12, 2) NOT NULL CHECK (unit_cost_at_issue >= 0)
);

CREATE TABLE equipment_assets (
    asset_id BIGINT PRIMARY KEY,
    asset_code VARCHAR(40) NOT NULL UNIQUE,
    equipment_name VARCHAR(120) NOT NULL,
    site_name VARCHAR(100) NOT NULL
);

CREATE TABLE maintenance_work_orders (
    work_order_id BIGINT PRIMARY KEY,
    asset_id BIGINT NOT NULL REFERENCES equipment_assets(asset_id),
    opened_at TIMESTAMP NOT NULL,
    status VARCHAR(20) NOT NULL CHECK (status IN ('open', 'in_progress', 'completed', 'cancelled')),
    priority VARCHAR(20) NOT NULL
);
